values.value:
{
  "fields": [
    {
      "apiName": "terms_and_conditions",
      "label": "Terms & Conditions",
      "type": "folder",
      "iconColor": "blue",
      "colSpan": 12,
      "modalConfigsByValue": {
        "default": {
          "title": "TERMS & CONDITIONS",
          "modalFields": [
            {
              "id": "payment_terms",
              "label": "Payment Terms",
              "expanded": true,
              "fields": [
                {
                  "apiName": "payment_terms",
                  "label": "Payment Terms",
                  "type": "picklist",
                  "options": [
                    "Before Dispatch",
                    "Against LC",
                    "Against PDC",
                    "Against Open Credit",
                    "Others"
                  ],
                  "colSpan": 12
                },
                {
                  "apiName": "lc_interest_reflect_separately",
                  "label": "LC Interest Reflect Separately",
                  "type": "number",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against LC"
                  ]
                },
                {
                  "apiName": "usance_interest_buyer_days",
                  "label": "(I) Usance Interest in Buyer's Account",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against LC"
                  ]
                },
                {
                  "apiName": "usance_interest_seller_days",
                  "label": "(II) Usance Interest in Seller's Account",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against LC"
                  ]
                },
                {
                  "apiName": "usance_interest_percentage",
                  "label": "(III) % of Usance Interest",
                  "type": "number",
                  "unit": "%",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against LC"
                  ]
                },
                {
                  "apiName": "against_pdc_days",
                  "label": "Against PDC",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against PDC"
                  ]
                },
                {
                  "apiName": "pdc_interest_percentage",
                  "label": "Interest (%)",
                  "type": "number",
                  "unit": "%",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against PDC"
                  ]
                },
                {
                  "apiName": "against_open_credit_days",
                  "label": "Against Open Credit",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against Open Credit"
                  ]
                },
                {
                  "apiName": "open_credit_interest_percentage",
                  "label": "Interest (%)",
                  "type": "number",
                  "unit": "%",
                  "colSpan": 12,
                  "controllingField": "payment_terms",
                  "controllingValues": [
                    "Against Open Credit"
                  ]
                }
              ]
            },
            {
              "id": "tnc_details",
              "label": "T&C Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "delivery_schedule",
                  "label": "Delivery Schedule",
                  "type": "text",
                  "unit": "Delivery Schedule",
                  "colSpan": 6
                },
                {
                  "apiName": "offer_validity",
                  "label": "Offer Validity",
                  "type": "text",
                  "unit": "Offer Validity",
                  "colSpan": 6
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
